export function page<T>(items: readonly T[], offset: number, limit: number): T[] {
  if (!Number.isSafeInteger(offset) || offset < 0) {
    throw new RangeError("offset must be a nonnegative safe integer");
  }
  if (!Number.isSafeInteger(limit) || limit < 0) {
    throw new RangeError("limit must be a nonnegative safe integer");
  }

  if (offset >= items.length || limit === 0) return [];

  const count = Math.min(limit, items.length - offset);
  return items.slice(offset, offset + count);
}

