import { expect, test } from "bun:test";
import { page } from "./page.ts";

test.each([
  { items: [10, 20, 30], offset: 0, limit: 2, expected: [10, 20] },
  { items: [10, 20, 30], offset: 1, limit: 1, expected: [20] },
  { items: [10, 20, 30], offset: 2, limit: 5, expected: [30] },
  { items: [10, 20, 30], offset: 3, limit: 1, expected: [] },
  { items: [10, 20, 30], offset: Number.MAX_SAFE_INTEGER, limit: 1, expected: [] },
  { items: [10, 20, 30], offset: 1, limit: Number.MAX_SAFE_INTEGER, expected: [20, 30] },
  { items: [10, 20, 30], offset: 1, limit: 0, expected: [] },
  { items: [], offset: 0, limit: 2, expected: [] },
])("returns the requested page: %j", ({ items, offset, limit, expected }) => {
  expect(page(items, offset, limit)).toEqual(expected);
});

test.each([-1, 0.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1])(
  "rejects invalid offset and limit: %s",
  (invalid) => {
    expect(() => page([10], invalid, 1)).toThrow(RangeError);
    expect(() => page([10], 0, invalid)).toThrow(RangeError);
  },
);

test("validates arguments before returning an empty page", () => {
  expect(() => page([], -1, 1)).toThrow(RangeError);
  expect(() => page([], 0, -1)).toThrow(RangeError);
  expect(() => page([10], -1, 0)).toThrow(RangeError);
  expect(() => page([10], 1, -1)).toThrow(RangeError);
});

test("preserves item references without changing the input", () => {
  const first = { id: 1 };
  const second = { id: 2 };
  const third = { id: 3 };
  const items = Object.freeze([first, second, third]);

  const result = page(items, 1, 2);

  expect(result).toHaveLength(2);
  expect(result[0]).toBe(second);
  expect(result[1]).toBe(third);
  expect(items).toEqual([first, second, third]);
});

